                                    let leaveConfirmed = false;
                                    let leaveUrl = null;



                                    $(document).on('click', 'a', function(e)
                                    {
                                        if (leaveConfirmed)
                                            return true;

                                        if ($(this).data('leave') === 'free')
                                            return true;

                                        leaveUrl = $(this).attr('href');
                                        console.log('leaveUrl 1');
                                        console.log(leaveUrl);
                                        if (
                                            !leaveUrl ||
                                            leaveUrl === '#' ||
                                            leaveUrl.startsWith('javascript:') ||
                                            $(this).attr('target') === '_blank'
                                        )
                                            return true;

                                        e.preventDefault();

                                        $('.openleavepopup').trigger('click'); // показать твое окно
                                    });

                                    $(document).on('click', '.leave-yes', function()
                                    {
                                        leaveConfirmed = true;
                                        console.log(leaveUrl);
                                        if (leaveUrl)
                                            window.location.href = leaveUrl;
                                    });


